using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using Cysharp.Threading.Tasks;using UnityEngine;using PaperPixelGames.Core.Managers;using PaperPixelGames.Core.Ai.NPCs;using PaperPixelGames.Framework.Patterns;using PaperPixelGames.Framework.Enums;using SushiAndFish.Casino;using SushiAndFish.CityExpansion;using Object=UnityEngine.Object;
public static partial class CityExpansionPlayAudit {
 [Serializable]public class RaisedBenchCase{public string anchor,resident,bench,error;public bool arrived,sit,visible,surfaceHit;public Vector3 target,actual,hips;public float poseError,seatSurface,hipSurfaceGap;}
 [Serializable]public class RaisedBenchReceipt{public string utc;public bool passed;public List<RaisedBenchCase> seats=new List<RaisedBenchCase>();}
 static async UniTask ValidateRaisedBenches(ParkCasinoIntegration c){var result=new RaisedBenchReceipt{utc=DateTime.UtcNow.ToString("o")};var scheduler=Object.FindFirstObjectByType<TownMealScheduler>();if(scheduler)scheduler.enabled=false;var pool=Singleton<ResidentManager>.Instance.Residents.Where(r=>r&&r.Runtime!=null&&(!scheduler||scheduler.IsEligible(r))&&r.GetComponentsInChildren<Animator>(true).Any(a=>a.isHuman)).ToArray();if(pool.Length==0)throw new Exception("No native humanoid NPC for bench verification");var anchors=Object.FindObjectsByType<WaypointAnchor>(FindObjectsSortMode.None).Where(a=>a.Category==ResidentActivityType.SeasideBench&&a.transform.position.z>8&&a.transform.position.z<25&&a.transform.position.x>-15&&a.transform.position.x<25).OrderBy(a=>a.Index).ToArray();var benches=Object.FindObjectsByType<MeshRenderer>(FindObjectsSortMode.None).Where(r=>FullPath(r.transform).StartsWith("Root/Bench/")).ToArray();for(int i=0;i<anchors.Length;i++){var anchor=anchors[i];var npc=pool[i%pool.Length];var target=anchor.transform.position;var row=new RaisedBenchCase{anchor=FullPath(anchor.transform),resident=npc.name,target=target};result.seats.Add(row);CompleteStage("NATIVE_BENCH_"+i);try{var brain=(ResidentBrain)typeof(ResidentController).GetField("_brain",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(npc);var animator=npc.GetComponentsInChildren<Animator>(true).First(a=>a.isHuman);animator.cullingMode=AnimatorCullingMode.AlwaysAnimate;brain.Movement.Warp(target-anchor.transform.forward*.8f,anchor.transform.rotation);brain.Runtime.TargetDestination=target;brain.Runtime.TargetRotation=anchor.transform.eulerAngles;brain.Runtime.HasValidTarget=true;brain.StateMachine.ChangeState(new ResidentMoveToScheduleTargetState(brain,ResidentActivityType.SeasideBench,20f),ResidentRequestPriority.HardReset);await Wait(()=>brain.Runtime.HasArrived&&Vector3.Distance(npc.transform.position,target)<.03f,15);await Pause(.6f);row.arrived=brain.Runtime.HasArrived;row.actual=npc.transform.position;row.poseError=Vector3.Distance(row.actual,target);row.sit=animator.GetBool("Sit");row.hips=animator.GetBoneTransform(HumanBodyBones.Hips).position;row.visible=animator.GetComponentsInChildren<SkinnedMeshRenderer>().Any(r=>r.enabled&&!r.forceRenderingOff);var bench=benches.OrderBy(b=>Vector2.Distance(new Vector2(b.bounds.center.x,b.bounds.center.z),new Vector2(target.x,target.z))).First();row.bench=FullPath(bench.transform);var temp=new GameObject("QA_seat_mesh_probe");temp.transform.SetPositionAndRotation(bench.transform.position,bench.transform.rotation);temp.transform.localScale=bench.transform.lossyScale;var collider=temp.AddComponent<MeshCollider>();collider.sharedMesh=bench.GetComponent<MeshFilter>().sharedMesh;Physics.SyncTransforms();row.surfaceHit=collider.Raycast(new Ray(target+Vector3.up*3,Vector3.down),out var hit,5);row.seatSurface=hit.point.y;row.hipSurfaceGap=row.hips.y-row.seatSurface;Object.Destroy(temp);if(!row.arrived||!row.sit||!row.visible||!row.surfaceHit||Mathf.Abs(row.hipSurfaceGap)>.32f)throw new Exception("Native NPC sit or seat contact did not match raised bench");if(i==0)await CoastView(c,"raised-bench-npc",target+anchor.transform.right*2+anchor.transform.forward*2+Vector3.up*.08f,target+Vector3.up*.65f);}catch(Exception ex){row.error=ex.ToString();completion.failures.Add("Raised native bench "+i+": "+ex.Message);}File.WriteAllText(Path.Combine(Reports,"screenshot-raised-bench-play.json"),JsonUtility.ToJson(result,true));}result.passed=anchors.Length==7&&result.seats.All(s=>string.IsNullOrEmpty(s.error)&&s.arrived&&s.sit&&s.visible);File.WriteAllText(Path.Combine(Reports,"screenshot-raised-bench-play.json"),JsonUtility.ToJson(result,true));if(!result.passed)throw new Exception("Raised native bench verification failed");}
}
